import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易附录纂注","description":"易附录纂注 - 易附录纂注","frontmatter":{"title":"易附录纂注","description":"易附录纂注 - 易附录纂注"},"headers":[],"relativePath":"zh/classics/yifulu-zuanzhu/001.md","filePath":"zh/classics/yifulu-zuanzhu/001.md"}'),r={name:"zh/classics/yifulu-zuanzhu/001.md"};function i(c,a,o,u,p,d){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易附录纂注",tabindex:"-1"},[n("易附录纂注 "),e("a",{class:"header-anchor",href:"#易附录纂注","aria-label":"Permalink to “易附录纂注”"},"​")],-1),e("p",null,"钦定四库全书经部一",-1),e("p",null,"易类提要",-1),e("p",null,"臣 等谨案：",-1),e("p",null,"易附录纂注十五卷，元胡一桂撰。一桂字庭芳，号双湖，婺源人。景定甲子领乡荐，试礼部不第，教授乡里以终。事迹具元史儒学传。是编以朱子本义为宗，取文集、语录之及于易者附之，谓之「附录」；取诸儒易说之合于本义者纂之，谓之「纂注」。其去取别裁，惟以朱子为断。元史称其受易源流出于朱子，殆以启蒙翼传及是书欤？陈栎称一桂此书于杨万里易传无半字及之。今检其所引栎说，信然。盖宋末元初，讲学者门户最严，而新安诸儒于授受源流辨别尤甚。万里易传虽远宗程子，而早工吟咏，与范成大、陆游齐名，不甚以讲学为事。故虽尝荐朱子，拒韩侂胄，而庆元党禁独不列名，一桂盖以词人摈之，未必尽以其书也。乾隆四十六年十月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。",-1)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
